def fmt(v):
    v = float(v)
    return str(int(v)) if v.is_integer() else f"{v:g}"


def unpack_input(path: Path, work: Path) -> Path:
    """Resolve either an extracted results folder or a ZIP to the actual result root."""
    if path.is_dir():
        # Normal case: results_R2_03/ directly contains the two experiment folders.
        if (path / "joint_spatiotemporal_sensitivity").is_dir() and (path / "cross_parameter_interactions").is_dir():
            return path
        # Also support an extra wrapper directory around results_R2_03.
        hits = list(path.rglob("joint_summary.csv"))
        for hit in hits:
            candidate = hit.parents[1]
            if (candidate / "joint_spatiotemporal_sensitivity").is_dir() and (candidate / "cross_parameter_interactions").is_dir():
                return candidate
        raise FileNotFoundError(
            f"Could not find joint_spatiotemporal_sensitivity/ and cross_parameter_interactions/ under: {path}"
        )
    if path.suffix.lower() != ".zip":
        raise ValueError("Input must be results_R2_03.zip or an extracted results_R2_03 directory")
    if work.exists():
        shutil.rmtree(work)
    work.mkdir(parents=True)
    with zipfile.ZipFile(path, "r") as zf:
        zf.extractall(work)
    direct = work / "results_R2_03"
    if (direct / "joint_spatiotemporal_sensitivity").is_dir() and (direct / "cross_parameter_interactions").is_dir():
        return direct
    hits = list(work.rglob("joint_summary.csv"))
    for hit in hits:
        candidate = hit.parents[1]
        if (candidate / "joint_spatiotemporal_sensitivity").is_dir() and (candidate / "cross_parameter_interactions").is_dir():
            return candidate
    raise FileNotFoundError("Could not locate the two expected result subfolders after extracting the ZIP")


def load_and_validate(root: Path):
    joint_dir = root / "joint_spatiotemporal_sensitivity"
    cross_dir = root / "cross_parameter_interactions"
    joint = pd.read_csv(joint_dir / "joint_summary.csv")
    cross = pd.read_csv(cross_dir / "cross_summary.csv")
    joint_raw = pd.read_csv(joint_dir / "joint_raw_results.csv")
    cross_raw = pd.read_csv(cross_dir / "cross_raw_results.csv")

    # Completion checks: fail loudly instead of silently plotting partial data.
    jc = json.loads((joint_dir / "joint_completion_status.json").read_text())
    cc = json.loads((cross_dir / "cross_completion_status.json").read_text())
    assert jc["actual_executions"] == jc["expected_actual_executions"] == 930, jc
    assert cc["actual_executions"] == cc["expected_actual_executions"] == 990, cc
    assert jc["smoke"] is False and cc["smoke"] is False

    # Every summary point must contain n=5 independent seeds.
    assert set(joint["n"].unique()) == {5}, joint["n"].value_counts().to_dict()
    assert set(cross["n"].unique()) == {5}, cross["n"].value_counts().to_dict()

    # Exact paired-task checks: within a given map/load/seed, all cells must share one task_hash.
    for raw in [joint_raw, cross_raw]:
        nunique = raw.groupby(["map", "task_count", "seed"])["task_hash"].nunique()
        assert int(nunique.max()) == 1, "Task pairing check failed"

    # Formal load and seed checks.
    expected_loads = {(m, N) for m in MAPS for N in LOADS[m].values()}
    observed_loads = set(map(tuple, joint_raw[["map", "task_count"]].drop_duplicates().values.tolist()))
    assert expected_loads == observed_loads
    assert set(joint_raw["seed"].unique()) == {10000, 10001, 10002, 10003, 10004}
    assert set(cross_raw["seed"].unique()) == {10000, 10001, 10002, 10003, 10004}

    return joint, cross, joint_raw, cross_raw


def summary_for(study: str, joint: pd.DataFrame, cross: pd.DataFrame) -> pd.DataFrame:
    src = joint if STUDIES[study]["source"] == "joint" else cross
    return src[src["study"] == study].copy()


def parse_cell(cell: str) -> dict[str, float]:
    out = {}
    for piece in str(cell).split("__"):
        k, v = piece.split("=")
        out[k] = float(v)
    return out


def success_matrix(study, map_name, load, joint, cross):
    spec = STUDIES[study]
    df = summary_for(study, joint, cross)
    s = df[(df["map"] == map_name) & (df["task_count"] == load) & (df["metric"] == "success_rate")].copy()
    xvals = spec["x_values"]
    yvals = spec["y_values"]
    M = np.full((len(yvals), len(xvals)), np.nan)
    for _, row in s.iterrows():
        p = parse_cell(row["cell"])
        x = p[spec["x"]]
        y = p[spec["y"]]
        xi = next(i for i, v in enumerate(xvals) if float(v) == float(x))
        yi = next(i for i, v in enumerate(yvals) if float(v) == float(y))
        M[yi, xi] = 100.0 * float(row["mean"])
    assert not np.isnan(M).any(), f"Incomplete matrix {study} {map_name} N={load}"
    b = s[s["cell"] == BASELINE_CELLS[study]]
    assert len(b) == 1
    baseline = 100.0 * float(b.iloc[0]["mean"])
    return M, baseline


def baseline_indices(spec):
    bx = float(spec["baseline"][spec["x"]])
    by = float(spec["baseline"][spec["y"]])
    xi = next(i for i, v in enumerate(spec["x_values"]) if float(v) == bx)
    yi = next(i for i, v in enumerate(spec["y_values"]) if float(v) == by)
    return xi, yi


def draw_delta_heatmap(ax, study, map_name, load, joint, cross, vmax=6.0, annotate=True):
    spec = STUDIES[study]
    M, baseline = success_matrix(study, map_name, load, joint, cross)
    D = M - baseline
    im = ax.imshow(D, cmap="RdBu", vmin=-vmax, vmax=vmax, aspect="auto", origin="upper")
    ax.set_xticks(np.arange(len(spec["x_values"])), [fmt(v) for v in spec["x_values"]])
    ax.set_yticks(np.arange(len(spec["y_values"])), [fmt(v) for v in spec["y_values"]])
    ax.set_xlabel(spec["x_label"])
    ax.set_ylabel(spec["y_label"])
    if annotate:
        for yi in range(D.shape[0]):
            for xi in range(D.shape[1]):
                val = D[yi, xi]
                txt_color = "white" if abs(val) >= 3.3 else "black"
                ax.text(xi, yi, f"{val:+.1f}", ha="center", va="center", fontsize=7.6, color=txt_color)
    xi, yi = baseline_indices(spec)
    ax.add_patch(Rectangle((xi - 0.5, yi - 0.5), 1, 1, fill=False, edgecolor="black", linewidth=2.0))
    for spine in ax.spines.values():
        spine.set_linewidth(1.3)
        spine.set_edgecolor(COLORS[map_name])
    return im, baseline, D


def add_common_colorbar(fig, im, label, rect=(0.925, 0.16, 0.016, 0.68)):
    cax = fig.add_axes(rect)
    cbar = fig.colorbar(im, cax=cax)
    cbar.set_label(label)
    return cbar

def make_response_combined(outdir, joint, cross):
    # Most informative response-letter view: high-load primary metric only.
    studies = ["sigma_l_sigma_t", "L_T", "gamma_sigma_l", "gamma_sigma_t", "gamma_K"]
    fig, axes = plt.subplots(3, 5, figsize=(18.0, 9.0))
    im = None
    for c, study in enumerate(studies):
        axes[0, c].set_title(STUDIES[study]["title"], pad=8, fontsize=12)
        for r, m in enumerate(MAPS):
            N = LOADS[m]["high"]
            im, baseline, D = draw_delta_heatmap(axes[r, c], study, m, N, joint, cross, vmax=6.0)
            if c == 0:
                axes[r, c].text(-0.25, 0.5, f"Map {m}\nN={N}\nBaseline={baseline:.1f}%",
                                transform=axes[r, c].transAxes, ha="right", va="center",
                                color=COLORS[m], fontweight="bold", fontsize=9.5)
    add_common_colorbar(fig, im, "Success-rate change from baseline (percentage points)", rect=(0.935, 0.18, 0.012, 0.64))
    fig.text(0.5, 0.012, "Black outline = formal baseline cell; high-load cases shown for compactness.", ha="center", fontsize=9)
    fig.subplots_adjust(left=0.075, right=0.91, bottom=0.075, top=0.94, wspace=0.34, hspace=0.34)
    png = outdir / "Figure_R2_03_Response_Combined.png"
    pdf = outdir / "Figure_R2_03_Response_Combined.pdf"
    fig.savefig(png, dpi=300, bbox_inches="tight")
    fig.savefig(pdf, dpi=300, bbox_inches="tight")
    plt.close(fig)
    return [png, pdf]


