def make_summary_tables(outdir, joint, cross):
    records = []
    for study in STUDIES:
        df = summary_for(study, joint, cross)
        for m in MAPS:
            N = LOADS[m]["high"]
            row = {"study": study, "map": m, "task_count": N}
            for metric in ["success_rate", "planning_time", "average_path_length"]:
                s = df[(df["map"] == m) & (df["task_count"] == N) & (df["metric"] == metric)]
                b = float(s[s["cell"] == BASELINE_CELLS[study]]["mean"].iloc[0])
                lo, hi = float(s["mean"].min()), float(s["mean"].max())
                if metric == "success_rate":
                    row["baseline_success_pct"] = 100 * b
                    row["success_min_pct"] = 100 * lo
                    row["success_max_pct"] = 100 * hi
                    row["success_range_pp"] = 100 * (hi - lo)
                elif metric == "planning_time":
                    row["baseline_time_s"] = b
                    row["time_min_s"] = lo
                    row["time_max_s"] = hi
                else:
                    row["baseline_APL"] = b
                    row["APL_min"] = lo
                    row["APL_max"] = hi
            records.append(row)
    detailed = pd.DataFrame(records)
    detailed_path = outdir / "Table_R2_03_HighLoad_Detailed.csv"
    detailed.to_csv(detailed_path, index=False)

    # Five-row manuscript summary, deliberately topology-aware rather than averaging maps together.
    compact = []
    for study in STUDIES:
        z = detailed[detailed["study"] == study]
        compact.append({
            "Interaction": STUDIES[study]["title"].replace("$", ""),
            "Success range Map A (pp)": z[z["map"] == "A"]["success_range_pp"].iloc[0],
            "Success range Map B (pp)": z[z["map"] == "B"]["success_range_pp"].iloc[0],
            "Success range Map C (pp)": z[z["map"] == "C"]["success_range_pp"].iloc[0],
            "Max planning time (s)": z["time_max_s"].max(),
            "APL range max (%)": max((z["APL_max"] - z["APL_min"]) / z["baseline_APL"] * 100),
        })
    compact = pd.DataFrame(compact)
    compact_path = outdir / "Table_MainText_R2_03_Summary.csv"
    compact.to_csv(compact_path, index=False)
    return [detailed_path, compact_path]


def nice_ylim(values, metric, percent=False):
    values = np.asarray(values, float)
    lo, hi = float(np.nanmin(values)), float(np.nanmax(values))
    if percent:
        # Same broad success-rate scale as R1, but ensure all R2 values are visible.
        return 65.0, 100.0
    if metric == "planning_time":
        upper = math.ceil(hi * 1.08 / 5.0) * 5.0
        return 0.0, max(5.0, upper)
    span = hi - lo
    pad = max(0.08 * span, 0.03 * max(abs(hi), 1.0), 0.1)
    return max(0.0, lo - pad), hi + pad


def make_supp_figure(outdir, study, joint, cross):
    spec = STUDIES[study]
    df = summary_for(study, joint, cross)
    # For R1-style sliced interactions, use x as first parameter and columns as fixed y parameter.
    rows = [
        ("success_rate", "Success rate (%)", True),
        ("planning_time", "Planning time (s)", False),
        ("average_path_length", "Average path length", False),
    ]
    ncols = len(spec["y_values"])
    fig, axes = plt.subplots(3, ncols, figsize=(4.0 * ncols, 9.7), squeeze=False)

    # Parse parameter coordinates once.
    sdf = df.copy()
    coords = sdf["cell"].map(parse_cell)
    sdf["x_value"] = [p[spec["x"]] for p in coords]
    sdf["y_value"] = [p[spec["y"]] for p in coords]
    sdf["load_level"] = ["low" if int(N) == LOADS[m]["low"] else "high" for m, N in zip(sdf["map"], sdf["task_count"])]

    for r, (metric, ylabel, percent) in enumerate(rows):
        all_metric = sdf[sdf["metric"] == metric]
        y_all = all_metric["mean"].to_numpy(float) * (100 if percent else 1)
        ylim = nice_ylim(y_all, metric, percent)
        for c, fixed_y in enumerate(spec["y_values"]):
            ax = axes[r, c]
            panel = all_metric[np.isclose(all_metric["y_value"].astype(float), float(fixed_y))]
            for m in MAPS:
                for load_level in ["low", "high"]:
                    ss = panel[(panel["map"] == m) & (panel["load_level"] == load_level)].sort_values("x_value")
                    x = ss["x_value"].to_numpy(float)
                    y = ss["mean"].to_numpy(float)
                    low = ss["ci95_low"].to_numpy(float)
                    high = ss["ci95_high"].to_numpy(float)
                    if percent:
                        y, low, high = y * 100, low * 100, high * 100
                    ax.errorbar(
                        x, y, yerr=[y - low, high - y],
                        color=COLORS[m], marker=MARKERS[m], linestyle=LOAD_STYLES[load_level],
                        linewidth=1.5, markersize=5, capsize=2.5,
                    )
            if r == 0:
                ax.set_title(rf"{spec['y_label']} = {fmt(fixed_y)}", pad=7)
            if c == 0:
                ax.set_ylabel(ylabel)
            if r == 2:
                ax.set_xlabel(spec["x_label"])
            ax.set_xticks(spec["x_values"], [fmt(v) for v in spec["x_values"]])
            ax.set_ylim(*ylim)
            ax.grid(True, alpha=0.25)
            ax.tick_params(direction="in")

    map_handles = [Line2D([0], [0], color=COLORS[m], marker=MARKERS[m], linestyle="-", linewidth=1.5, markersize=5, label=f"Map {m}") for m in MAPS]
    load_handles = [
        Line2D([0], [0], color="black", linestyle=LOAD_STYLES["low"], linewidth=1.5, label="Lower traffic load"),
        Line2D([0], [0], color="black", linestyle=LOAD_STYLES["high"], linewidth=1.5, label="Higher traffic load"),
    ]
    fig.legend(handles=map_handles + load_handles, loc="upper center", ncol=5, frameon=False, bbox_to_anchor=(0.5, 1.002))
    fig.tight_layout(rect=[0, 0, 1, 0.965])
    stem = f"Figure_Supp_R2_03_{study}"
    png = outdir / f"{stem}.png"
    pdf = outdir / f"{stem}.pdf"
    fig.savefig(png, dpi=300, bbox_inches="tight")
    fig.savefig(pdf, dpi=300, bbox_inches="tight")
    plt.close(fig)
    return [png, pdf]


def make_supplementary(outdir, joint, cross):
    outputs = []
    for study in STUDIES:
        outputs += make_supp_figure(outdir, study, joint, cross)
    return outputs


def write_captions(outdir, joint, cross):
    text = """# R2-03 figure package - recommended use\n\n## Response letter\nUse `Figure_R2_03_Response_CoreGaussian` followed by `Figure_R2_03_Response_CrossInteractions` if the combined 3x5 figure is too small. The panels show high-load mean success-rate changes relative to the formal baseline. This is the most direct response metric because the manuscript defines planning success rate as the primary one-shot metric. The black outline marks the formal baseline cell. All values come from five paired seeds (10000-10004) using identical task sets within each map/load/seed.\n\nSuggested caption:\n**Figure R2-03. Multidimensional parameter sensitivity of CPS-A*.** Each heatmap reports the change in mean planning success rate (percentage points) relative to the formal baseline under the higher tested traffic load (Map A: 70 tasks; Map B: 280; Map C: 200). The black outline identifies the baseline cell. The full low- and high-load results, including 95% confidence intervals for success rate, planning time, and average path length, are reported in the Supplementary Material.\n\n## Main manuscript\nUse `Figure_MainText_R2_03_CoreGaussian` for the two Gaussian spatiotemporal interactions requested most directly by the reviewer (`sigma_l x sigma_t` and `L x T`). Use `Table_MainText_R2_03_Summary.csv` to summarize all five interactions without adding multiple large figures to the main text.\n\nSuggested caption:\n**Figure X. Multidimensional sensitivity of the Gaussian spatiotemporal parameters under high traffic loads.** Colors show the change in mean planning success rate relative to the formal baseline; the baseline cell is outlined in black. Across the tested parameter region, the width interaction is comparatively stable, whereas the support interaction (`L x T`) shows greater sensitivity, particularly on the constrained Map A and for computational cost.\n\n## Supplementary Material\nUse the five `Figure_Supp_R2_03_*` figures. They intentionally follow the R1 visual language: Map A/B/C are red/blue/green; circle/square/triangle markers encode map; solid/dashed lines encode lower/higher traffic load. Rows show Success Rate, Planning Time, and Average Path Length (APL). Every point is the mean over five seeds with a 95% confidence interval.\n\n## Metric choice\n- **Response letter primary metric: Success Rate.** It is the manuscript's primary one-shot performance metric and directly addresses robustness of routing feasibility.\n- **Planning Time:** retained in Supplementary and summary table because it reveals substantial computational trade-offs, especially for `L x T`; it is not used as the sole response-letter metric because it measures cost rather than the main routing-feasibility conclusion.\n- **Average Path Length (APL):** retained as the third Supplementary metric because it is an explicit manuscript path-efficiency metric.\n- **Average waits:** not used in the publication-facing figures because it is not one of the manuscript's named primary one-shot metrics.\n- **average_congestion_fixed:** excluded because it is an internal evaluator field and is identically zero in the submitted R2-03 result files.\n"""
    path = outdir / "README_Figure_Selection_and_Captions.md"
    path.write_text(text, encoding="utf-8")
    return [path]


def main():
    ap = argparse.ArgumentParser(
        description="Generate R2-03 figures from the results_R2_03 folder. Can run with no arguments when the folder is beside this script."
    )
    ap.add_argument(
        "--input", default=None,
        help="Optional path to results_R2_03 folder or ZIP. If omitted, auto-detect beside the script or in the current directory."
    )
    ap.add_argument(
        "--output", default=None,
        help="Optional output directory. If omitted, figures are written to R2_03_publication_figures beside this script."
    )
    args = ap.parse_args()

    script_dir = Path(__file__).resolve().parent
    cwd = Path.cwd()

    # If --input was not supplied, find a nearby extracted folder or ZIP automatically.
    if args.input:
        inp = Path(args.input).expanduser()
        if not inp.is_absolute() and not inp.exists():
            beside_script = script_dir / inp
            if beside_script.exists():
                inp = beside_script
        inp = inp.resolve()
    else:
        candidates = [
            script_dir / "results_R2_03",
            cwd / "results_R2_03",
            script_dir / "results_R2_03.zip",
            cwd / "results_R2_03.zip",
        ]
        inp = next((p.resolve() for p in candidates if p.exists()), None)
        if inp is None:
            raise FileNotFoundError(
                "Cannot auto-find results_R2_03. Put the results_R2_03 folder beside this script, "
                "or run with --input path\to\results_R2_03."
            )

    if args.output:
        out = Path(args.output).expanduser()
        if not out.is_absolute():
            out = cwd / out
        out = out.resolve()
    else:
        out = (script_dir / "R2_03_publication_figures").resolve()

    if out == inp:
        raise ValueError("Output directory must not be the same as the input results directory/file.")
    if out.exists():
        shutil.rmtree(out)
    out.mkdir(parents=True)
    work = out / "_tmp_extract"
    root = unpack_input(inp, work)
    joint, cross, joint_raw, cross_raw = load_and_validate(root)

    response = out / "01_response_letter"
    manuscript = out / "02_main_manuscript"
    supplementary = out / "03_supplementary"
    for d in [response, manuscript, supplementary]:
        d.mkdir(parents=True)

    generated = []
    generated += make_response_combined(response, joint, cross)
    generated += make_response_split(response, joint, cross)
    generated += make_maintext_core(manuscript, joint, cross)
    generated += make_summary_tables(manuscript, joint, cross)
    generated += make_supplementary(supplementary, joint, cross)
    generated += write_captions(out, joint, cross)

    if inp.is_file() and work.exists():
        shutil.rmtree(work)

    print("Validated formal result set and generated:")
    for p in generated:
        print(p)


if __name__ == "__main__":
    main()
